(1, 2, 1, 'course_completion_certificate', 'Course Completion Certificate', '{\"heading\":\"Certificate Of Completion\",\"content_part_1\":\"This is to certify that\",\"learner\":\"{learner_name}\",\"content_part_2\":\"has successfully completed \\\"{course_name}\\\" \\\"{course_language}\\\" online course on {course_completed_date} in duration {course_duration}.\",\"trainer\":\"Tutor: {teacher_name}\",\"certificate_number\":\"Certificate No.: {certificate_number}\"}', '{learner_name} Learner name <br>\r\n{teacher_name} Teacher name <br>\r\n{course_name} Course Title <br>\r\n{course_language} Course Language<br>\r\n{course_completed_date} Course Completed On <br>\r\n{certificate_number} Certificate Number<br>\r\n{course_duration} Course Duration<br><br>', 1, '2022-03-15 04:00:00', '2025-02-28 05:42:40', NULL),
(3, 2, 2, 'course_completion_certificate', 'Course Completion Certificate', '{\"heading\":\"شهادة إتمام\",\"content_part_1\":\"هذا للتصديق على ذلك\",\"learner\":\"{learner_name}\",\"content_part_2\":\"أكمل بنجاح دورة \\\"{course_name}\\\" \\\"{course_language}\\\" عبر الإنترنت على {course_completed_date} في المدة {course_duration}.\",\"trainer\":\"المعلم: {teacher_name}\",\"certificate_number\":\"رقم الشهادة: {certificate_number}\"}', '{learner_name} Learner name <br>\r\n{teacher_name} Teacher name <br>\r\n{course_name} Course Title <br>\r\n{course_language} Course Language<br>\r\n{course_completed_date} Course Completed On <br>\r\n{certificate_number} Certificate Number<br>\r\n{course_duration} Course Duration<br><br>', 1, '2022-03-15 04:00:00', '2022-05-09 10:53:38', NULL),
(7, 1, 1, 'evaluation_certificate', 'Evaluation Certificate', '{\"heading\": \"Certificate Of Evaluation\", \"learner\": \"{learner_name}\", \"trainer\": \"Tutor:  {teacher_name}\", \"content_part_1\": \"This is to certify that\", \"content_part_2\": \"has successfully completed \\\"{quiz_name}\\\" online quiz on {quiz_completed_date} in {quiz_duration} and has achieved {quiz_score} score.\", \"certificate_number\": \"Certificate No.:  {certificate_number}\"}', '{learner_name} Learner name <br>\r\n{teacher_name} Teacher name <br>\r\n{quiz_name} Quiz Title <br>\r\n{quiz_completed_date} Quiz Completed On <br>\r\n{certificate_number} Certificate Number<br>\r\n{quiz_duration} Quiz Duration<br>\r\n{quiz_score} Score in Percent<br><br>', 1, '2022-09-19 04:00:00', '2022-09-19 04:00:00', NULL),
