('completed_course_settlement_email_to_teacher', 1, 'Course Payment Received', 'Course Payment Received', '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Course Payment Received</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {username}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">We are glad to inform you that one of your course payment has been settled and credited to your wallet. Below are the complete details:</p>\r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">          \r\n									<tbody>\r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Course Title</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{course_title}</td>\r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Amount Credited</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{amount}</td>\r\n										</tr>                             \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{username} Teacher name<br>\r\n{course_title} Course title<br>\r\n{amount} Amount Credited<br>{website_name} - Website Name<br>', 1, 0),
('completed_course_settlement_email_to_teacher', 2, 'تم استلام مدفوعات الدورة التدريبية', 'تم استلام مدفوعات الدورة التدريبية', '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تم استلام مدفوعات الدورة التدريبية</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {username}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">يسعدنا إبلاغك بأنه تم تسوية إحدى دفعات الدورة التدريبية الخاصة بك وإضافتها إلى محفظتك. فيما يلي التفاصيل الكاملة:</p>\r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">          \r\n									<tbody>\r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">عنوان الدورة</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{course_title}</td>\r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">المبلغ المضاف</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{amount}</td>\r\n										</tr>                             \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{username} Teacher name<br>\r\n{course_title} Course title<br>\r\n{amount} Amount Credited<br>{website_name} - Website Name<br>', 1, 0),
('completed_course_settlement_email_to_teacher', 3, 'Pago del curso recibido', 'Pago del curso recibido', '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Pago del curso recibido</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {username}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Nos complace informarle que uno de los pagos de su curso ha sido liquidado y acreditado en su billetera. A continuación se muestran los detalles completos:</p>\r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">          \r\n									<tbody>\r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Título del curso</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{course_title}</td>\r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Monto acreditado</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{amount}</td>\r\n										</tr>                             \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{username} Teacher name<br>\r\n{course_title} Course title<br>\r\n{amount} Amount Credited<br>{website_name} - Website Name<br>', 1, 0),
('contact_us', 1, 'Contact-Us', 'Contact Us Form Submitted on {website_name}', '\r\n<table width=\"600\" cellspacing=\" 0\" cellpadding=\" 0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\" background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\" 100%\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\" align=\" center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\" padding:20px 0;\">                                \r\n								<h5 style=\" margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\" margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Contact Us Request</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\" background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\" 100%\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\" align=\" center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\" padding:40px 0 60px;\">                                \r\n								<h3 style=\" margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear Admin</h3>                                \r\n								<p style=\" font-size: 14px; line-height: 20px;color: #676767;\">A user has submitted a\r\n                                    contact request. Below are the details:</p>                                \r\n								<table style=\" border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">Name</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">Email Address<span class=\" Apple-tab-span\" style=\" white-space:pre\"></span></td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{email_address}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">Phone Number</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{phone_number}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">Message</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{message}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{name} User name<br>\r\n{email_address} User email<br>\r\n{phone_number} User phone<br>\r\n{message} Message from user<br>{website_name} - Website Name<br>', 1, 1),
('contact_us', 2, 'اتصل بنا', 'نموذج الاتصال بنا المقدم في {website_name}', '\r\n<table width=\"600\" cellspacing=\" 0\" cellpadding=\" 0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\" background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\" 100%\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\" align=\" center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\" padding:20px 0;\">                                \r\n								<h5 style=\" margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\" margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">طلب اتصل بنا</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\" background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\" 100%\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\" align=\" center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\" padding:40px 0 60px;\">                                \r\n								<h3 style=\" margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي المشرف</h3>                                \r\n								<p style=\" font-size: 14px; line-height: 20px;color: #676767;\">أرسل المستخدم\r\n                                    طلب الاتصال. فيما يلي التفاصيل:</p>                                \r\n								<table style=\" border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">اسم</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">عنوان البريد الإلكتروني<span class=\" Apple-tab-span\" style=\" white-space:pre\"></span></td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{email_address}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">رقم الهاتف</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{phone_number}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">رسالة</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{message}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{name} User name<br>\r\n{email_address} User email<br>\r\n{phone_number} User phone<br>\r\n{message} Message from user<br>{website_name} - Website Name<br>', 1, 1);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('contact_us', 3, 'Contáctanos', 'Formulario de contacto enviado el {website_name}', '\r\n<table width=\"600\" cellspacing=\" 0\" cellpadding=\" 0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\" background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\" 100%\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\" align=\" center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\" padding:20px 0;\">                                \r\n								<h5 style=\" margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\" margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Contacta con nosotros Solicitar</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\" background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\" 100%\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\" align=\" center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\" padding:40px 0 60px;\">                                \r\n								<h3 style=\" margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado administrador</h3>                                \r\n								<p style=\" font-size: 14px; line-height: 20px;color: #676767;\">Un usuario ha enviado un archivo\r\n                                    Solicitud de contacto. A continuación se muestran los detalles:</p>                                \r\n								<table style=\" border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\" 0\" cellpadding=\" 0\" border=\" 0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">Nombre</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">Dirección de correo electrónico<span class=\" Apple-tab-span\" style=\" white-space:pre\"></span></td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{email_address}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">Número de teléfono</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{phone_number}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\" padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\" 153\">Mensaje</td>                                            \r\n											<td style=\" padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\" 620\">{message}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{name} User name<br>\r\n{email_address} User email<br>\r\n{phone_number} User phone<br>\r\n{message} Message from user<br>{website_name} - Website Name<br>', 1, 0),
('course_approval_request_email_to_admin', 1, 'Course Approval Request Received', 'Course Approval Request Received', '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Course Request Received</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear Admin</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">A new course named \"{course_title}\" has been submitted by {username} for approval. Please verify the details and process the request further.<br />\r\n									<br />