                                  \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{username} User Full Name<br>\r\n{email} User Email<br>\r\n{request_status} Request Stauts<br>\r\n{data_removal_status} Data is removed or not<br>\r\n{declined_reason} Request declined reason<br>\r\n{website_name} - Website Name<br>', 1, 0),
('emails_header_footer_layout', 1, 'Email Header/Footer Layout', 'Email Header/Footer Layout', '<table dir=\"{dir}\" style=\"font-family:Arial; color:#333; line-height:26px;\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" bgcolor=\"#f5f5f5\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:{primary-color};padding:30px 0;\"><br />\r\n				</td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:{primary-color};padding:0 0 0;\">                \r\n				<!--\r\n				header start here\r\n				-->\r\n				                \r\n				<table style=\"background: #fff;border-bottom: 1px solid #eee;\" width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 40px;\"><a href=\"#\" style=\"display: block;\"><img src="/images/logo.svg" alt="w3mentors" /></a></td>                            \r\n							<td style=\"text-align:{stylecls}; padding: 40px;\"> {social_media_icons}\r\n                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>                \r\n				<!--\r\n				header end here\r\n				-->\r\n				            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td>                \r\n				<!--\r\n				page body start here\r\n				-->\r\n				                {email_body}\r\n\r\n                \r\n				<!--\r\n				page body end here\r\n				-->\r\n				            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td>                \r\n				<!--\r\n				page footer start here\r\n				-->\r\n				                \r\n				<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						                       \r\n						<tr>                            \r\n							<td style=\"backgr