('feedback_mail_to_teacher', 3, 'Correo de retroalimentación al maestro', 'Reseña del alumno', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\">                                </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">                                    Nueva revisión</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">                                    Estimado {teacher_name}</h3>                                                       \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">{learner_name} le ha dado una reseña que ahora está publicada. Visite su perfil para verificar la revisión.&nbsp;<br />\r\n									</p> </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner name <br>\r\n{teacher_name} Teacher Name\r\n<br>{website_name} - Website Name<br>', 1, 0),
('forgot_password', 1, 'Forgot Password Email', 'Password reset instructions at {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Forgot Password!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {user_full_name}</h3>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">It seems that you forgot your password!<br />\r\n									                                                                We received a request to reset the password for your account.</p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">To reset your password, click on the below button:<br />\r\n									                                                                <a href=\"{reset_url}\" style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\">Click here</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"> Or copy and paste the below url into your browser:<br />\r\n									                                                                <a style=\"color: {primary-color};\">{reset_url}</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />\r\n									Please note that the link is valid for next 24 hours only.</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{user_full_name} Full Name of the email receiver<br>\r\n{reset_url} Reset Url<br>\r\n{website_name} - Website Name<br>', 1, 1),
('forgot_password', 2, 'نسيت كلمة المرور البريد الإلكتروني', 'تعليمات إعادة تعيين كلمة المرور في {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">نسيت كلمة المرور!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {user_full_name}</h3>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">يبدو أنك نسيت كلمة المرور الخاصة بك!<br />تلقينا طلبا لإعادة تعيين كلمة المرور لحسابك.</p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">لإعادة تعيين كلمة المرور الخاصة بك ، انقر فوق الزر أدناه:<br />\r\n									                                                                <a href=\"{reset_url}\" style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\">اضغط هنا</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"> أو انسخ والصق عنوان url أدناه في متصفحك:<br />\r\n									                                                                <a style=\"color: {primary-color};\">{reset_url}</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />يرجى ملاحظة أن الرابط صالح لمدة 24 ساعة القادمة فقط.</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{user_full_name} Full Name of the email receiver<br>\r\n{reset_url} Reset Url<br>\r\n{website_name} - Website Name<br>', 1, 1),
('forgot_password', 3, 'Olvidé mi contraseña Correo electrónico', 'Instrucciones para restablecer la contraseña en {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">¡Olvidé mi contraseña!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {user_full_name}</h3>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">¡Parece que olvidaste tu contraseña!<br />Recibimos una solicitud para restablecer la contraseña de su cuenta.</p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Para restablecer su contraseña, haga clic en el botón de abajo:<br />\r\n									                                                                <a href=\"{reset_url}\" style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\">Haga clic aquí</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"> O copie y pegue la siguiente URL en su navegador:<br />\r\n									                                                                <a style=\"color: {primary-color};\">{reset_url}</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />Tenga en cuenta que el enlace es válido solo durante las próximas 24 horas.</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{user_full_name} Full Name of the email receiver<br>\r\n{reset_url} Reset Url<br>\r\n{website_name} - Website Name<br>', 1, 0),
('giftcard_admin', 1, 'Gift Card Purchased', 'Gift Card Purchased on {website_name}!', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Gift Card Purchased</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear Admin</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">A new gift card order was placed. Below are the details:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Sender Name</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{sender_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Receiver Name<span class=\"Apple-tab-span\" style=\"white-space:pre\"></span></td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{recipient_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Receiver Email</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{recipient_email}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Amount</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{giftcard_amount}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Code</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{giftcard_code}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table> ', '{sender_name} Sender name<br>\r\n{recipient_name} Receiver name<br>\r\n{recipient_email} Receiver email<br>\r\n{giftcard_amount} Gitft Card amount<br>\r\n{giftcard_code} Gift Card Code<br>{website_name} - Website Name<br>', 1, 0),
('giftcard_admin', 2, 'تم شراء بطاقة الهدايا', 'بطاقة هدايا تم شراؤها في {website_name}!', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تم شراء بطاقة الهدايا</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي المشرف</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">تم تقديم طلب بطاقة هدايا جديدة. فيما يلي التفاصيل:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">اسم المرسل</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{sender_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">اسم المستلم<span class=\"Apple-tab-span\" style=\"white-space:pre\"></span></td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{recipient_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">البريد الإلكتروني للمستلم</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{recipient_email}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">مبلغ</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{giftcard_amount}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">رمز</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{giftcard_code}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table> ', '{sender_name} Sender name<br>\r\n{recipient_name} Receiver name<br>\r\n{recipient_email} Receiver email<br>\r\n{giftcard_amount} Gitft Card amount<br>\r\n{giftcard_code} Gift Card Code<br>{website_name} - Website Name<br>', 1, 0);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('giftcard_admin', 3, 'Tarjeta de regalo comprada', '¡Tarjeta de regalo comprada en {website_name}!', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Tarjeta de regalo comprada</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado administrador</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Se realizó un nuevo pedido de tarjeta de regalo. A continuación se muestran los detalles:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Nombre del remitente</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{sender_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Nombre del destinatario<span class=\"Apple-tab-span\" style=\"white-space:pre\"></span></td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{recipient_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Correo electrónico del receptor</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{recipient_email}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Importe</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{giftcard_amount}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Código</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{giftcard_code}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table> ', '{sender_name} Sender name<br>\r\n{recipient_name} Receiver name<br>\r\n{recipient_email} Receiver email<br>\r\n{giftcard_amount} Gitft Card amount<br>\r\n{giftcard_code} Gift Card Code<br>{website_name} - Website Name<br>', 1, 0),
('giftcard_recipient', 1, 'Gift Card Email To Recipient', '{sender_name} sent you a Gift Card on {website_name} !', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\"> \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Gift Card Recieved!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {recipient_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">We are happy to inform you that {sender_name} has sent you a Gift card</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Your Gift card code is <span style=\" border: 3px dotted #ddd;padding: 5px 10px;font-weight: bold\">{giftcard_code}</span></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />\r\n									In order to redeem your gift, please visit the <a style=\"color: {primary-color}\" href=\"{website_url}\">{website_name}</a></p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table> ', '{recipient_name} Receiver name<br>{sender_name} Sender name<br>{giftcard_code} Gift Card Code<br>{website_name} Website name<br>{website_url} - Website Url<br>', 1, 0),
('giftcard_recipient', 2, 'بطاقة الهدايا البريد الإلكتروني إلى المستلم', 'أرسل لك {sender_name} بطاقة هدايا على {website_name}!', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\"> \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تم استلام بطاقة الهدايا!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {recipient_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">يسعدنا إبلاغك بأن {sender_name} قد أرسل لك بطاقة هدايا</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">رمز بطاقة الهدايا الخاصة بك هو <span style=\" border: 3px dotted #ddd;padding: 5px 10px;font-weight: bold\">{giftcard_code}</span></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />من أجل استرداد هديتك ، يرجى زيارة <a style=\"color: {primary-color}\" href=\"{website_url}\">{website_name}</a></p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table> ', '{recipient_name} Receiver name<br>{sender_name} Sender name<br>{giftcard_code} Gift Card Code<br>{website_name} Website name<br>{website_url} - Website Url<br>', 1, 0),
('giftcard_recipient', 3, 'Tarjeta de regalo por correo electrónico al destinatario', '{sender_name} le envió una tarjeta de regalo el {website_name} !', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\"> \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">¡Tarjeta de regalo recibida!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {recipient_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Nos complace informarle que {sender_name} le ha enviado una tarjeta de regalo</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">El código de tu tarjeta regalo es <span style=\" border: 3px dotted #ddd;padding: 5px 10px;font-weight: bold\">{giftcard_code}</span></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />Para canjear su regalo, visite el <a style=\"color: {primary-color}\" href=\"{website_url}\">{website_name}</a></p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table> ', '{recipient_name} Receiver name<br>{sender_name} Sender name<br>{giftcard_code} Gift Card Code<br>{website_name} Website name<br>{website_url} - Website Url<br>', 1, 0),
('giftcard_redeem', 1, 'Gift Card Redeemed', 'Gift Card Redeemed!', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\"> \r\n                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Gift Card Redeemed</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {sender_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">We would like to inform you that the gift card you have shared with {receiver_name} has been redeemed successfully.<br />\r\n									<br />\r\n									Gift card code : {giftcard_code}</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{sender_name} Sender name<br>\r\n{receiver_name} Receiver name<br>\r\n{giftcard_code} Gift card code<br>{website_name} - Website Name<br>', 1, 0),
('giftcard_redeem', 2, 'تم استرداد بطاقة الهدايا', 'تم استرداد بطاقة الهدايا!', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\"> \r\n                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تم استرداد بطاقة الهدايا</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {sender_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">نود إبلاغك بأن بطاقة الهدايا التي شاركتها مع {receiver_name} قد تم استردادها بنجاح.<br />\r\n									<br />رمز بطاقة الهدايا : {giftcard_code}</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{sender_name} Sender name<br>\r\n{receiver_name} Receiver name<br>\r\n{giftcard_code} Gift card code<br>{website_name} - Website Name<br>', 1, 0),
('giftcard_redeem', 3, 'Tarjeta de regalo canjeada', '¡Tarjeta de regalo canjeada!', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\"> \r\n                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Tarjeta de regalo canjeada</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {sender_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Nos gustaría informarle que la tarjeta de regalo que ha compartido con {receiver_name} se ha canjeado con éxito.<br />\r\n									<br />Código de la 