('learner_issue_reported_email', 1, 'Issue Reported Email To Teacher', 'Learner Reported An Issue at {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Learner Reported An Issue</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {teacher_name} </h3>                                \r\n								<p style=\"font-size: 14px;line-height: 20px;color: #676767;\">{learner_name} has raised a concern for one of your {session_type}. We request you to check the issue reported by the learner and take the required action.</p>                                                                \r\n								<p style=\"font-size: 14px;line-height: 20px;color: #676767;\">Here are the complete details:</p>                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">{session_type} Name</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{class_lesson_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Scheduled On</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{schedule_date} {start_time} - {end_time}</td>                                        \r\n										</tr>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Reason/Comment</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_comment}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner Name<br>\r\n{teacher_name} Teacher Name<br>\r\n{session_type} Class or Lesson <br>\r\n{class_lesson_name} Class Name or Lesson Name <br>\r\n{learner_comment} Learner comment<br>\r\n{schedule_date} Scheduled date<br>\r\n{start_time} Start time<br>\r\n{end_time} End Time<br>{website_name} - Website Name<br>', 1, 0),
('learner_issue_reported_email', 2, 'تم الإبلاغ عن مشكلة البريد الإلكتروني للمعلم', 'أبلغ المتعلم عن مشكلة في {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">أبلغ المتعلم عن مشكلة</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {teacher_name} </h3>                                \r\n								<p style=\"font-size: 14px;line-height: 20px;color: #676767;\">أثار {learner_name} قلقا بشأن أحد {session_type} الخاص بك. نطلب منك التحقق من المشكلة التي أبلغ عنها المتعلم واتخاذ الإجراء المطلوب.</p>                                                                \r\n								<p style=\"font-size: 14px;line-height: 20px;color: #676767;\">فيما يلي التفاصيل الكاملة:</p>                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">{session_type} اسم</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{class_lesson_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">مجدول في</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{schedule_date} {start_time} - {end_time}</td>                                        \r\n										</tr>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">السبب/التعليق</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_comment}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner Name<br>\n{teacher_name} Teacher Name<br>\n{session_type} Class or Lesson <br>\n{class_lesson_name} Class Name or Lesson Name <br>\n{learner_comment} Learner comment<br>\n{schedule_date} Scheduled date<br>\n{start_time} Start time<br>\n{end_time} End Time<br>{website_name} - Website Name<br>', 1, 0);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('learner_issue_reported_email', 3, 'Emitir un correo electrónico reportado al profesor', 'El alumno ha informado de un problema en {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">El alumno ha informado de un problema</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {teacher_name} </h3>                                \r\n								<p style=\"font-size: 14px;line-height: 20px;color: #676767;\">{learner_name} ha planteado una preocupación por uno de sus {session_type}. Le solicitamos que compruebe el problema notificado por el alumno y tome las medidas necesarias.</p>                                                                \r\n								<p style=\"font-size: 14px;line-height: 20px;color: #676767;\">Aquí están los detalles completos:</p>                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">{session_type} Nombre</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{class_lesson_name}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Programado el</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{schedule_date} {start_time} - {end_time}</td>                                        \r\n										</tr>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Motivo/Comentario</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_comment}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner Name<br> {teacher_name} Teacher Name<br> {session_type} Class or Lesson <br> {class_lesson_name} Class Name or Lesson Name <br> {learner_comment} Learner comment<br> {schedule_date} Scheduled date<br> {start_time} Start time<br> {end_time} End Time<br>{website_name} - Website Name<br>', 1, 0),
('learner_lesson_book_email', 1, 'Lessons Booking Email To Learner', 'Lessons Booked at {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n        \r\n	<tbody> \r\n                \r\n		<tr> \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\"> \r\n                               \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n                                        \r\n					<tbody> \r\n \r\n                                                \r\n						<tr> \r\n \r\n                                                        \r\n							<td style=\"padding:20px 0;\"> \r\n \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5> \r\n \r\n                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Booking Successful!</h2> </td> \r\n \r\n                                                \r\n						</tr> \r\n \r\n                                        \r\n					</tbody> \r\n \r\n                                \r\n				</table> </td> \r\n \r\n                \r\n		</tr> \r\n \r\n                \r\n		<tr> \r\n \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \"> \r\n \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n \r\n                                        \r\n					<tbody> \r\n \r\n                                                \r\n						<tr> \r\n \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\"> \r\n \r\n                                                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {learner_name} </h3> \r\n \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Congratulations!!<br />\r\n									                                                                         </p> \r\n \r\n \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">You have successfully completed the booking process.</p> \r\n \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Your booking for the lessons \"{tlang_name}\" is confirmed with the teacher \"{teacher_name}\".</p> \r\n \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><a href=\"{lesson_url}\" target=\"_blank\">Click here to view lessons</a><br />\r\n									                                                                         Thanks for booking with us!!</p> </td> \r\n \r\n                                                \r\n						</tr> \r\n \r\n                                        \r\n					</tbody> \r\n \r\n                                \r\n				</table> </td> \r\n \r\n                \r\n		</tr> \r\n \r\n        \r\n	</tbody>\r\n</table>', '{learner_name} Learner name<br>{teacher_name} Teacher Name<br>{tlang_name} Teach language name<br>{lesson_url} Lesson url<br>{website_url} Website url<br>{website_name} - Website Name<br>', 1, 0),
('learner_lesson_book_email', 2, 'حجز الدروس البريد الإلكتروني للمتعلم', 'الدروس المحجوزة في {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n        \r\n	<tbody> \r\n                \r\n		<tr> \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\"> \r\n                               \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n                                        \r\n					<tbody> \r\n \r\n                                                \r\n						<tr> \r\n \r\n                                                        \r\n							<td style=\"padding:20px 0;\"> \r\n \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5> \r\n \r\n                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تم الحجز بنجاح!</h2> </td> \r\n \r\n                                                \r\n						</tr> \r\n \r\n                                        \r\n					</tbody> \r\n \r\n                                \r\n				</table> </td> \r\n \r\n                \r\n		</tr> \r\n \r\n                \r\n		<tr> \r\n \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \"> \r\n \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n \r\n                                        \r\n					<tbody> \r\n \r\n                                                \r\n						<tr> \r\n \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\"> \r\n \r\n                                                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {learner_name} </h3> \r\n \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">مبروك!!<br />\r\n									                                                                         </p> \r\n \r\n \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">لقد أكملت عملية الحجز بنجاح.</p> \r\n \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">يتم تأكيد حجزك للدروس \"{tlang_name}\" مع المعلم \"{teacher_name}\".</p> \r\n \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><a href=\"{lesson_url}\" target=\"_blank\">انقر هنا لعرض الدروس</a><br />شكرا للحجز معنا! !</p> </td> \r\n \r\n                                                \r\n						</tr> \r\n \r\n                                        \r\n					</tbody> \r\n \r\n                                \r\n				</table> </td> \r\n \r\n                \r\n		</tr> \r\n \r\n        \r\n	</tbody>\r\n</table>', '{learner_name} Learner name<br>{teacher_name} Teacher Name<br>{tlang_name} Teach language name<br>{lesson_url} Lesson url<br>{website_url} Website url<br>{website_name} - Website Name<br>', 1, 0),
('learner_lesson_book_email', 3, 'Correo electrónico de reserva de lecciones para el alumno', 'Lecciones reservadas en {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n        \r\n	<tbody> \r\n                \r\n		<tr> \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\"> \r\n                               \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n                                        \r\n					<tbody> \r\n \r\n                                                \r\n						<tr> \r\n \r\n                                                        \r\n							<td style=\"padding:20px 0;\"> \r\n \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5> \r\n \r\n                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">¡Reserva exitosa!</h2> </td> \r\n \r\n                                                \r\n						</tr> \r\n \r\n                                        \r\n					</tbody> \r\n \r\n                                \r\n				</table> </td> \r\n \r\n                \r\n		</tr> \r\n \r\n                \r\n		<tr> \r\n \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \"> \r\n \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\"> \r\n \r\n                                        \r\n					<tbody> \r\n \r\n                                                \r\n						<tr> \r\n \r\n                        