('learner_reschedule_email', 1, 'Learner Rescheduled Lesson', 'Lesson Rescheduled at {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Lesson {action}!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {teacher_name} </h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"> \"{learner_name}\" has {action} a lesson with you. Please see the details below:</p>                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Lesson Name</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_name}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Scheduled On</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_date}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Time Slot</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_start_time} - {lesson_end_time}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Comment</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_comment}</td>                                                                                \r\n										</tr>                                                                        \r\n									</tbody>                                                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner name <br>\r\n{teacher_name} Teacher name <br>\r\n{lesson_name} Scheduled Lesson <br>\r\n{learner_comment} Learner message <br>\r\n{lesson_date} Scheduled Date <br>\r\n{lesson_start_time} Scheduled Start Time <br>\r\n{lesson_end_time} Lesson end time <br>\r\n{action} Scheduled or Rescheduled<br>{website_name} - Website Name<br>', 1, 1),
('learner_reschedule_email', 2, 'درس المتعلم المعاد جدولته', 'تمت إعادة جدولة الدرس في {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">الدرس {action}!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {teacher_name} </h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"> \"{learner_name}\" لديه {action} درس معك. يرجى الاطلاع على التفاصيل أدناه:</p>                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">اسم الدرس</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_name}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">مجدول في</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_date}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">الفترة الزمنية</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_start_time} - {lesson_end_time}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">التعليق</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_comment}</td>                                                                                \r\n										</tr>                                                                        \r\n									</tbody>                                                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner name <br>\r\n{teacher_name} Teacher name <br>\r\n{lesson_name} Scheduled Lesson <br>\r\n{learner_comment} Learner message <br>\r\n{lesson_date} Scheduled Date <br>\r\n{lesson_start_time} Scheduled Start Time <br>\r\n{lesson_end_time} Lesson end time <br>\r\n{action} Scheduled or Rescheduled<br>{website_name} - Website Name<br>', 1, 1);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('learner_reschedule_email', 3, 'Lección reprogramada por el alumno', 'Lección reprogramada en {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">¡Lección {action}!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {teacher_name} </h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"> \"{learner_name}\" tiene {action} una lección contigo. Consulte los detalles a continuación:</p>                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Nombre de la lección</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_name}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Programado el</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_date}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Franja horaria</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_start_time} - {lesson_end_time}</td>                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Comentario</td>                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_comment}</td>                                                                                \r\n										</tr>                                                                        \r\n									</tbody>                                                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner name <br>\r\n{teacher_name} Teacher name <br>\r\n{lesson_name} Scheduled Lesson <br>\r\n{learner_comment} Learner message <br>\r\n{lesson_date} Scheduled Date <br>\r\n{lesson_start_time} Scheduled Start Time <br>\r\n{lesson_end_time} Lesson end time <br>\r\n{action} Scheduled or Rescheduled<br>{website_name} - Website Name<br>', 1, 0),
