('order_paid_to_admin', 2, 'دفع الطلب تلقى البريد الإلكتروني إلى المسؤول', 'تم استلام دفعة الطلب', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:20px 0;\">                                \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> تم استلام الدفعة</h2>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                                                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> عزيزي المشرف</h3>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">مبروك!!<br />\r\n									                                                                        <br />تم تقديم طلب جديد وتم استلام مدفوعاته بنجاح.</p>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">فيما يلي تفاصيل الطلب:</p>                                \r\n                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">اسم المستخدم</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{customer}</td>                                        \r\n                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> رقم الطلب</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\"><a href=\"{order_link}\" style=\"color: {primary-color};\" target=\"_blank\">{orderid}</a></td>                                        \r\n                                                                                \r\n										</tr>                                        \r\n                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> المبلغ المدفوع</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n                                                                        \r\n									</tbody>                                \r\n                                                                \r\n								</table>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>    \r\n        \r\n	</tbody>\r\n</table> ', '{customer} Learner name<br>\r\n{payment} Amount Paid <br>\r\n{orderid} Order Id<br>\r\n{order_link} Order Link<br>{website_name} - Website Name<br>', 1, 0);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('order_paid_to_admin', 3, 'Pago del pedido recibido por correo electrónico al administrador', 'Pago del pedido recibido', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:20px 0;\">                                \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> Pago recibido</h2>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                                                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> Estimado administrador</h3>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">¡¡Felicidades!!<br />\r\n									                                                                        <br />Se ha realizado un nuevo pedido y su pago se ha recibido con éxito.</p>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">A continuación se muestran los detalles del pedido:</p>                                \r\n                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Nombre de usuario</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{customer}</td>                                        \r\n                                                                                \r\n										</tr>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Id. de pedido</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\"><a href=\"{order_link}\" style=\"color: {primary-color};\" target=\"_blank\">{orderid}</a></td>                                        \r\n                                                                                \r\n										</tr>                                        \r\n                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Monto pagado</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n                                                                        \r\n									</tbody>                                \r\n                                                                \r\n								</table>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>    \r\n        \r\n	</tbody>\r\n</table> ', '{customer} Learner name<br>\r\n{payment} Amount Paid <br>\r\n{orderid} Order Id<br>\r\n{order_link} Order Link<br>{website_name} - Website Name<br>', 1, 0),
('order_paid_to_customer', 1, 'Order Payment Email To Learner', 'Order Payment Received', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> Payment Successful</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> Dear {customer}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Congratulations!!<br />\r\n									<br />\r\n									We are glad to inform you that your order booking is complete and its payment has been received successfully.</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Below are the order details:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Order Id</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{orderid}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Amount Paid</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />\r\n									Thanks for booking with us!!</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{customer} Learner name<br>\r\n{orderid} Order id <br>\r\n{payment} Amount Paid <br>{website_name} - Website Name<br>', 1, 0),
('order_paid_to_customer', 2, 'طلب الدفع عبر البريد الإلكتروني للمتعلم', 'تم استلام دفعة الطلب', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> تم الدفع بنجاح</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> عزيزي {customer}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">مبروك!!<br />\r\n									<br />يسعدنا إبلاغك بأن حجز طلبك قد اكتمل وتم استلام دفعه بنجاح.</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">فيما يلي تفاصيل الطلب:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> رقم الطلب</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{orderid}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> المبلغ المدفوع</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />شكرا للحجز معنا! !</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{customer} Learner name<br>\r\n{orderid} Order id <br>\r\n{payment} Amount Paid <br>{website_name} - Website Name<br>', 1, 0),
('order_paid_to_customer', 3, 'Solicitar correo electrónico de pago al alumno', 'Pago del pedido recibido', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> Pago exitoso</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> Estimado {customer}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">¡¡Felicidades!!<br />\r\n									<br />Nos complace informarle que la reserva de su pedido se ha completado y que su pago se ha recibido con éxito.</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">A continuación se muestran los detalles del pedido:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Id. de pedido</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{orderid}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Monto pagado</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />¡Gracias por reservar con nosotros!</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{customer} Learner name<br>\r\n{orderid} Order id <br>\r\n{payment} Amount Paid <br>{website_name} - Website Name<br>', 1, 0),
('password_changed_successfully', 1, 'Password Changed Successfully', 'Password Changed Successfully at {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Congratulations</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {user_full_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">This mail is to ensure that you have recently updated your password.<br />\r\n									 Your password update process is successful and now you can login with your new password.</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><a style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\" href=\"{login_link}\">Login</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />\r\n									If you have not updated your password, we recommend you to reset your password immediately or contact admin.</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table> ', '{user_full_name} Full Name of the email receiver.<br/>\r\n{login_link} Login page link<br>{website_name} - Website Name<br>', 1, 0),
