('rep_by_question_reported_request_status_change', 2, 'تم الإبلاغ عن السؤال تغيير حالة الطلب - تم الإبلاغ عنه بواسطة', 'تغيير الحالة في طلب السؤال الذي تم الإبلاغ عنه', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\"> \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تم الإبلاغ عن تغيير حالة السؤال!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {reported_by_full_name}</h3> \r\n \r\n								<p>الطلب&nbsp;المبلغ عنه بشأن السؤال \"{question_title}\" هو \"{status}\" الذي نشره المؤلف \"{reported_by_full_name}\".</p>\r\n								<p>تعليقات: {admin_comments}<br />\r\n									</p></td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{reported_by_full_name} Full Name of Reported user <br>\r\n{author_full_name} Full Name of Author<br>\r\n{status} changed status<br>\r\n{question_title} - Question title<br>\r\n{admin_comments} - Comments added by Admin\r\n<br>{website_name} - Website Name<br>', 1, 0),
('rep_by_question_reported_request_status_change', 3, 'Cambio de estado de solicitud notificada por la pregunta - Notificado por', 'Cambio de estado en la solicitud de pregunta notificada', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\"> \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">¡Cambio de estado de la pregunta reportada!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {reported_by_full_name}</h3> \r\n \r\n								<p>La solicitud&nbsp;reportada sobre la pregunta \"{question_title}\" ha sido \"{status}\" publicada por el autor <span style=\"font-weight: bold;\">\"{reported_by_full_name}</span>\".<span style=\"font-weight: bold;\"></span><span style=\"font-weight: bold;\"></span></p>\r\n								<p><span style=\"font-weight: bold;\">\"Comentarios</span>\": {admin_comments}<br />\r\n									</p></td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{reported_by_full_name} Full Name of Reported user <br>\r\n{author_full_name} Full Name of Author<br>\r\n{status} changed status<br>\r\n{question_title} - Question title<br>\r\n{admin_comments} - Comments added by Admin\r\n<br>{website_name} - Website Name<br>', 1, 0);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('subscription_booking_email_to_admin', 1, 'Subscription Purchased Email To Admin', 'Subscription Purchased', '\r\n\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:20px 0;\">                                \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> Subscription Purchased</h2>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                                                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> Dear Admin</h3>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">We are glad to inform you that a subscription order has been received from a learner on {website_name}.</p>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Below are the subscription details:</p>                                \r\n                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Learner Name</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_name}</td>                                        \r\n                                                                                \r\n										</tr> \r\n<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Subscription Plan</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{subscription_plan}</td>                                        \r\n                                                                                \r\n										</tr>                                        \r\n                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Amount Paid</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n										  <tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Validity</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date} - {end_date}</td>                                        \r\n                                                                                \r\n										</tr>  \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Duration</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{duration}</td>                                        \r\n                                                                                \r\n										</tr> \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Lesson Count</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_count}</td>                                        \r\n                                                                                \r\n										</tr> 										\r\n									</tbody>                                \r\n                                                                \r\n								</table>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>    \r\n        \r\n	</tbody>\r\n</table> ', '{learner_name} Learner name <br>\r\n{subscription_plan} Plan Name<br>\r\n{payment} Price<br>\r\n{start_date} - {end_date} Start & Expiry Date<br>\r\n{duration} Lesson duration<br>\r\n{lesson_count} Lessons count<br>{website_name} - Website Name<br>', 1, 0),
('subscription_booking_email_to_admin', 2, 'تم شراء الاشتراك عبر البريد الإلكتروني إلى المشرف', 'تم شراء الاشتراك', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:20px 0;\">                                \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> تم شراء الاشتراك</h2>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                                                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> عزيزي المشرف</h3>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">يسعدنا أن نعلمك أنه قد تم استلام طلب اشتراك من أحد المتعلمين على {website_name}.</p>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">وفيما يلي تفاصيل الاشتراك:</p>                                \r\n                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">اسم المتعلم</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_name}</td>                                        \r\n                                                                                \r\n										</tr> <tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">خطة الاشتراك</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{subscription_plan}</td>                                        \r\n                                                                                \r\n										</tr>                                          \r\n                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> المبلغ المدفوع</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> صلاحية</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date} - {end_date}</td>                                        \r\n                                                                                \r\n										</tr>   \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> مدة</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{duration}</td>                                        \r\n                                                                                \r\n										</tr> \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> عدد الدروس</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_count}</td>                                        \r\n                                                                                \r\n										</tr>                             \r\n									</tbody>                                \r\n                                                                \r\n								</table>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>    \r\n        \r\n	</tbody>\r\n</table> ', '{learner_name} Learner name <br>\r\n{subscription_plan} Plan Name<br>\r\n{payment} Price<br>\r\n{start_date} - {end_date} Start & Expiry Date<br>\r\n{duration} Lesson duration<br>\r\n{lesson_count} Lessons count<br>{website_name} - Website Name<br>', 1, 0),
('subscription_booking_email_to_admin', 3, 'Suscripción comprada Correo electrónico al administrador', 'Suscripción comprada', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:20px 0;\">                                \r\n                                                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> Suscripción comprada</h2>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                                                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> Estimado administrador</h3>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Nos complace informarle que se recibió un pedido de suscripción de un alumno en {website_name}.</p>                                \r\n                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">A continuación se muestran los detalles de la suscripción:</p>                                \r\n                                                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Nombre del alumno</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{learner_name}</td>                                        \r\n                                                                                \r\n										</tr>  <tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Plan de suscripción</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{subscription_plan}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Monto pagado</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Validez</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date} - {end_date}</td>                                        \r\n                                                                                \r\n										</tr>   \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Duración</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{duration}</td>                                        \r\n                                                                                \r\n										</tr> \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Recuento de lecciones</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_count}</td>                                        \r\n                                                                                \r\n										</tr>                                \r\n									</tbody>                                \r\n                                                                \r\n								</table>                            </td>                        \r\n                                                \r\n						</tr>                    \r\n                                        \r\n					</tbody>                \r\n                                \r\n				</table>            </td>        \r\n                \r\n		</tr>    \r\n        \r\n	</tbody>\r\n</table> ', '{learner_name} Learner name <br>\r\n{subscription_plan} Plan Name<br>\r\n{payment} Price<br>\r\n{start_date} - {end_date} Start & Expiry Date<br>\r\n{duration} Lesson duration<br>\r\n{lesson_count} Lessons count<br>{website_name} - Website Name<br>', 1, 0),
('subscription_booking_email_to_learner', 1, 'Subscription Purchased Email To Learner', 'Subscription Purchased', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> Subscription Purchased</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> Dear {learner_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Congratulations!!<br />\r\n									<br />We\'re excited to confirm that your subscription booking process is completed successfully on {website_name}.</p>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Below are the subscription details:</p>   \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Subscription Plan</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{subscription_plan}</td>                                        \r\n                                                                                \r\n										</tr>                                     \r\n                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Amount Paid</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n										  <tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Validity</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date} - {end_date}</td>                                        \r\n                                                                                \r\n										</tr>  \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Duration</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{duration}</td>                                        \r\n                                                                                \r\n										</tr> \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Lesson Count</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_count}</td>                                        \r\n                                                                                \r\n										</tr> 										\r\n									</tbody>                                \r\n                                                                \r\n								</table>                                                           \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />\r\n									Thanks for choosing us!!</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner name <br>\r\n{subscription_plan} Plan Name<br>\r\n{payment} Price<br>\r\n{start_date} - {end_date} Start & Expiry Date<br>\r\n{duration} Lesson duration<br>\r\n{lesson_count} Lessons count<br>{website_name} - Website Name<br>', 1, 0),
('subscription_booking_email_to_learner', 2, 'الاشتراك الذي تم شراؤه عبر البريد الإلكتروني للمتعلم', 'تم شراء الاشتراك', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> تم شراء الاشتراك</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> عزيزي {learner_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">تهانينا!!<br />\r\n									<br />يسعدنا أن نؤكد أن عملية حجز اشتراكك قد اكتملت بنجاح على {website_name}.</p>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">وفيما يلي تفاصيل الاشتراك:</p>   \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">خطة الاشتراك</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{subscription_plan}</td>                                        \r\n                                                                                \r\n										</tr>                                     \r\n                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> المبلغ المدفوع</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n										  <tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> صلاحية</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date} - {end_date}</td>                                        \r\n                                                                                \r\n										</tr>  \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> مدة</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{duration}</td>                                        \r\n                                                                                \r\n										</tr> \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">عدد الدروس</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_count}</td>                                        \r\n                                                                                \r\n										</tr> 										\r\n									</tbody>                                \r\n                                                                \r\n								</table>                                                           \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />\r\n									شكرا لاختيارك لنا!</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner name <br>\r\n{subscription_plan} Plan Name<br>\r\n{payment} Price<br>\r\n{start_date} - {end_date} Start & Expiry Date<br>\r\n{duration} Lesson duration<br>\r\n{lesson_count} Lessons count<br>{website_name} - Website Name<br>', 1, 0),
('subscription_booking_email_to_learner', 3, 'Suscripción comprada Correo electrónico al alumno', 'Suscripción comprada', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"> </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\"> Suscripción comprada</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\"> Querida  {learner_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">¡¡Felicidades!!<br />\r\n									<br />Nos complace confirmar que el proceso de reserva de su suscripción se completó correctamente en {website_name}.</p>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">A continuación se muestran los detalles de la suscripción:</p>   \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n                                                                        \r\n									<tbody>                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Plan de suscripción</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{subscription_plan}</td>                                        \r\n                                                                                \r\n										</tr>                                     \r\n                                                                                \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Cantidad pagada</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{payment}</td>                                        \r\n                                                                                \r\n										</tr>                                    \r\n										  <tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Validez</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date} - {end_date}</td>                                        \r\n                                                                                \r\n										</tr>  \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Duración</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{duration}</td>                                        \r\n                                                                                \r\n										</tr> \r\n										<tr>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\"> Recuento de lecciones</td>                                            \r\n                                                                                        \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{lesson_count}</td>                                        \r\n                                                                                \r\n										</tr> 										\r\n									</tbody>                                \r\n                                                                \r\n								</table>                                                           \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />\r\n									Gracias por elegirnos!!</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{learner_name} Learner name <br>\r\n{subscription_plan} Plan Name<br>\r\n{payment} Price<br>\r\n{start_date} - {end_date} Start & Expiry Date<br>\r\n{duration} Lesson duration<br>\r\n{lesson_count} Lessons count<br>{website_name} - Website Name<br>', 1, 0);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('subscription_plan_cancelled_mail_to_admin', 1, 'Subscription Cancelled Mail To Admin', 'Subscription Plan Cancelled', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Subscription Cancelled</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                               