('subscription_plan_exhausted_mail_to_learner', 1, 'Subscription Plan Exhausted', 'Subscription Plan Exhausted', '\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \n        \n	<tbody>        \n                \n		<tr>            \n                        \n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \n                                \n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \n					<tbody>                        \n						<tr>                            \n							<td style=\"padding:20px 0;\">                                \n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Subscription Exhausted</h2>                            </td>                        \n						</tr>                    \n					</tbody>                \n				</table>            </td>                \n		</tr>        \n                \n		<tr>            \n                        \n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \n                                \n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \n                                        \n					<tbody>                        \n                                                \n						<tr>                            \n                                                        \n							<td style=\"padding:40px 0 60px;\">                                \n                                                                \n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {learner_name} </h3>                                \n                                                                \n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">This email is to inform you that your current subscription plan has exhausted. You have booked and consumed all the lessons. </p>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">Your subscription will be autorenewed on the renewal date but you can also renew the same manually from your subscriptions list.</p>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">Below are your current subscription details:</p>\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                                                        \n									<tbody>  \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Subscription Plan</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{plan_name}</td>                                                                                \n										</tr> \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Start Date</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date}</td>                                                                                \n										</tr>  \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">End Date</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{end_date}</td> \n                                                                               \n										</tr> \n										<tr>\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Amount</td>\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{amount}</td> \n										</tr>                                                                   \n									</tbody>                                                                \n								</table>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">Thanks for subscribing with us!!</p>\n								</td>                        \n                                                \n						</tr>                    \n                                        \n					</tbody>                \n                                \n				</table>            </td>        \n                \n		</tr>    \n        \n	</tbody>\n</table>  ', '{plan_name} - subscription plan name<br>\n{learner_name} - subscription Learner name<br>\n{start_date} - subscription start date<br>\n{end_date} -  subscription end date<br>\n{amount} - subscription order amount<br>{website_name} - Website Name<br>', 1, 0),
('subscription_plan_exhausted_mail_to_learner', 2, 'استنفدت خطة الاشتراك', 'استنفدت خطة الاشتراك', '\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \n        \n	<tbody>        \n                \n		<tr>            \n                        \n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \n                                \n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \n					<tbody>                        \n						<tr>                            \n							<td style=\"padding:20px 0;\">                                \n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تم استنفاد الاشتراك</h2>                            </td>                        \n						</tr>                    \n					</tbody>                \n				</table>            </td>                \n		</tr>        \n                \n		<tr>            \n                        \n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \n                                \n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \n                                        \n					<tbody>                        \n                                                \n						<tr>                            \n                                                        \n							<td style=\"padding:40px 0 60px;\">                                \n                                                                \n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">{learner_name} عزيزي</h3>                                \n                                                                \n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">تهدف هذه الرسالة الإلكترونية إلى إبلاغك بأن خطة اشتراكك الحالية قد استنفدت. لقد حجزت واستهلكت جميع الدروس. </p>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">سيتم تجديد اشتراكك تلقائيًا في تاريخ التجديد، ولكن يمكنك أيضًا تجديده يدويًا من قائمة الاشتراكات الخاصة بك.</p>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">فيما يلي تفاصيل اشتراكك الحالي:</p>\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                                                        \n									<tbody>  \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">خطة الاشتراك</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{plan_name}</td>                                                                                \n										</tr> \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">تاريخ البدء</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date}</td>                                                                                \n										</tr>  \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">تاريخ الانتهاء</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{end_date}</td> \n                                                                               \n										</tr> \n										<tr>\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">كمية</td>\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{amount}</td> \n										</tr>                                                                   \n									</tbody>                                                                \n								</table>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">شكرا لأشتراكك معنا!!</p>\n								</td>                        \n                                                \n						</tr>                    \n                                        \n					</tbody>                \n                                \n				</table>            </td>        \n                \n		</tr>    \n        \n	</tbody>\n</table>  ', '{plan_name} - subscription plan name<br>\n{learner_name} - subscription Learner name<br>\n{start_date} - subscription start date<br>\n{end_date} -  subscription end date<br>\n{amount} - subscription order amount<br>{website_name} - Website Name<br>', 1, 0),
('subscription_plan_exhausted_mail_to_learner', 3, 'Plan de suscripción agotado', 'Plan de suscripción agotado', '\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \n        \n	<tbody>        \n                \n		<tr>            \n                        \n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \n                                \n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \n					<tbody>                        \n						<tr>                            \n							<td style=\"padding:20px 0;\">                                \n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Suscripción agotada</h2>                            </td>                        \n						</tr>                    \n					</tbody>                \n				</table>            </td>                \n		</tr>        \n                \n		<tr>            \n                        \n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \n                                \n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \n                                        \n					<tbody>                        \n                                                \n						<tr>                            \n                                                        \n							<td style=\"padding:40px 0 60px;\">                                \n                                                                \n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimada {learner_name} </h3>                                \n                                                                \n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">Este correo electrónico es para informarle que su plan de suscripción actual se ha agotado. Has reservado y consumido todas las lecciones.</p>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">Su suscripción se renovará automáticamente en la fecha de renovación, pero también puede renovarla manualmente desde su lista de suscripciones.</p>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">A continuación se muestran los detalles de su suscripción actual:</p>\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                                                        \n									<tbody>  \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Plan de suscripción</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{plan_name}</td>                                                                                \n										</tr> \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Fecha de inicio	</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date}</td>                                                                                \n										</tr>  \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Fecha final</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{end_date}</td> \n                                                                               \n										</tr> \n										<tr>\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Cantidad</td>\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{amount}</td> \n										</tr>                                                                   \n									</tbody>                                                                \n								</table>\n								<p style=\"font-size: 14px; line-height: 20px; color: #676767;\">Gracias por suscribirte con nosotras !!</p>\n								</td>                        \n                                                \n						</tr>                    \n                                        \n					</tbody>                \n                                \n				</table>            </td>        \n                \n		</tr>    \n        \n	</tbody>\n</table>  ', '{plan_name} - subscription plan name<br>\n{learner_name} - subscription Learner name<br>\n{start_date} - subscription start date<br>\n{end_date} -  subscription end date<br>\n{amount} - subscription order amount<br>{website_name} - Website Name<br>', 1, 0),
('subscription_plan_inactive_mail_to_learner', 1, 'Subscription Inactive Mail To Learner', 'Subscription Plan Inactive For Future Renewals', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Subscription Deactivated</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                                                                \r\n                              \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {learner_name} </h3>                                \r\n                                                                \r\n                              \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">This is to inform you that your current active subscription plan \"{plan_name}\" is no longer available. Your current cycle will not get affected but the subscription will be discontinued once expired.\r\n								<br>\r\n								To continue with our services, you can still purchase a new <a href=\"{subscriptions_link}\" style=\"color: {primary-color};\" target=\"_blank\">subscription plan</a>.</p>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">\r\n								For more details, please contact the site admin.</p>                                                                \r\n								                                                             </td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>                        \r\n                                                \r\n		</tr>                    \r\n                                        \r\n	</tbody>                \r\n                                \r\n</table>                    \r\n                \r\n		    \r\n         ', '{plan_name} - subscription plan name<br>\r\n{learner_name} - subscription Learner name<br>\r\n{subscriptions_link} - Subscriptions page link<br>{website_name} - Website Name<br>', 1, 0);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('subscription_plan_inactive_mail_to_learner', 2, 'الاشتراك غير نشط البريد إلى المتعلم', 'خطة الاشتراك غير نشطة للتجديدات المستقبلية', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تم إلغاء الاشتراك</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                                                                \r\n                              \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">{learner_name} عزيزي  </h3>                                \r\n                                                                \r\n                              \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">هذا لإعلامك بأن خطة الاشتراك النشطة الحالية \"{plan_name}\" لم تعد متوفرة. لن تتأثر دورتك الحالية ولكن سيتم إيقاف الاشتراك بمجرد انتهاء صلاحيته.\r\n								<br>\r\n								لمواصلة خدماتنا، لا يزال بإمكانك شراء <a href=\"{subscriptions_link}\" style=\"color: {primary-color};\" target=\"_blank\">خطة الاشتراك</a></p>\r\n								\r\n								\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">\r\n								لمزيد من التفاصيل يرجى التواصل مع إدارة الموقع.</p>                                                                \r\n								                                                             </td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>                        \r\n                                                \r\n		</tr>                    \r\n                                        \r\n	</tbody>                \r\n                                \r\n</table>                    \r\n                \r\n		    \r\n         ', '{plan_name} - subscription plan name<br>\r\n{learner_name} - subscription Learner name<br>\r\n{subscriptions_link} - Subscriptions page link<br>{website_name} - Website Name<br>', 1, 0),
('subscription_plan_inactive_mail_to_learner', 3, 'Correo inactivo de suscripción al alumno', 'Plan de suscripción inactivo para futuras renovaciones', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n        \r\n	<tbody>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Suscripción desactivada</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>                \r\n		</tr>        \r\n                \r\n		<tr>            \r\n                        \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n                                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n                                        \r\n					<tbody>                        \r\n                                                \r\n						<tr>                            \r\n                                                        \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n                                                                \r\n                              \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Querida {learner_name} </h3>                                \r\n                                                                \r\n                              \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Le informamos que su plan de suscripción activo actual \"{plan_name}\" ya no está disponible. Su ciclo actual no se verá afectado, pero la suscripción se suspenderá una vez que expire.\r\n								<br>\r\n								Para continuar con nuestros servicios, aún puedes comprar un nuevo <a href=\"{subscriptions_link}\" style=\"color: {primary-color};\" target=\"_blank\">plan de suscripción</a>.</p>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">\r\n								Para obtener más detalles, comuníquese con el administrador del sitio.</p>                                                                \r\n								                                                             </td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>                        \r\n                                                \r\n		</tr>                    \r\n                                        \r\n	</tbody>                \r\n                                \r\n</table>                    \r\n                \r\n		    \r\n         ', '{plan_name} - subscription plan name<br>\r\n{learner_name} - subscription Learner name<br>\r\n{subscriptions_link} - Subscriptions page link<br>{website_name} - Website Name<br>', 1, 0),
('subscription_plan_renewed_mail_to_learner', 1, 'Subscription Plan Renewal Email to Learner', 'Subscription plan renewed Successfully', '\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \n        \n	<tbody>        \n                \n		<tr>            \n                        \n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \n                                \n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \n					<tbody>                        \n						<tr>                            \n							<td style=\"padding:20px 0;\">                                \n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Subscription Renewed</h2>                            </td>                        \n						</tr>                    \n					</tbody>                \n				</table>            </td>                \n		</tr>        \n                \n		<tr>            \n                        \n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \n                                \n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \n                                        \n					<tbody>                        \n                                                \n						<tr>                            \n                                                        \n							<td style=\"padding:40px 0 60px;\">                                \n                                                                \n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {learner_name} </h3>                                \n                                                                \n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">This is to update you that your current subscription plan has been renewed successfully. Below are the details: </p>                                                                \n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                                                        \n									<tbody>  \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Subscription Plan</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{plan_name}</td>                                                                                \n										</tr> \n                                      \n										<tr>                                                                                        \n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Start Date</td>                                                                                        \n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{start_date}</td>                                                                                \n										</tr>  \n                                      \n										<tr>                                                    