('unread_messages_email', 1, 'Unread Messages Email', 'You have {unread_messages_count} unread message(s) at {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"border-bottom-style: solid; border-bottom-color: rgb(238, 238, 238); background: rgb(255, 255, 255); padding: 0px 40px; text-align: center; color: rgb(153, 153, 153); vertical-align: top;\">\r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n					<tbody>\r\n						<tr>\r\n							<td style=\"padding: 20px 0px;\">\r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>\r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Unread Messages Notification!</h2></td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom-style: solid; border-bottom-color: rgb(238, 238, 238); background: rgb(255, 255, 255); padding: 0px 40px 50px; color: rgb(153, 153, 153); vertical-align: top;\">\r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n					<tbody>\r\n						<tr>\r\n							<td style=\"padding: 40px 0px 60px;\">\r\n								<h3 style=\"margin: 0px 0px 10px; font-size: 24px; font-weight: 500; padding: 0px; color: rgb(51, 51, 51); text-align: center;\">Dear {user_full_name}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px; color: rgb(103, 103, 103);\">Here are some notifications you have missed from the below thread(s):</p>{messages_detail}</td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>\r\n		</tr>\r\n	</tbody>\r\n</table>', '{user_full_name} Name of the email receiver.<br>\r\n{unread_messages_count} Unread messages count.<br>\r\n{messages_detail} Threads list.<br>\r\n{website_name} Name of our website<br>', 1, 0),
('unread_messages_email', 2, 'البريد الإلكتروني للرسائل غير المقروءة', 'لديك {unread_messages_count} رسالة (رسائل) غير مقروءة في {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"border-bottom-style: solid; border-bottom-color: rgb(238, 238, 238); background: rgb(255, 255, 255); padding: 0px 40px; text-align: center; color: rgb(153, 153, 153); vertical-align: top;\">\r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n					<tbody>\r\n						<tr>\r\n							<td style=\"padding: 20px 0px;\">\r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>\r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">إشعار الرسائل غير المقروءة!</h2></td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom-style: solid; border-bottom-color: rgb(238, 238, 238); background: rgb(255, 255, 255); padding: 0px 40px 50px; color: rgb(153, 153, 153); vertical-align: top;\">\r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n					<tbody>\r\n						<tr>\r\n							<td style=\"padding: 40px 0px 60px;\">\r\n								<h3 style=\"margin: 0px 0px 10px; font-size: 24px; font-weight: 500; padding: 0px; color: rgb(51, 51, 51); text-align: center;\">عزيزي {user_full_name}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px; color: rgb(103, 103, 103);\">فيما يلي بعض الإشعارات التي فاتتك من الموضوع (المواضيع) أدناه:</p>{messages_detail}</td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>\r\n		</tr>\r\n	</tbody>\r\n</table>', '{user_full_name} Name of the email receiver.<br>\r\n{unread_messages_count} Unread messages count.<br>\r\n{messages_detail} Threads list.<br>\r\n{website_name} Name of our website<br>', 1, 0),
('unread_messages_email', 3, 'Mensajes no leídos Correo electrónico', 'Tienes {unread_messages_count} mensaje(s) sin leer en {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"border-bottom-style: solid; border-bottom-color: rgb(238, 238, 238); background: rgb(255, 255, 255); padding: 0px 40px; text-align: center; color: rgb(153, 153, 153); vertical-align: top;\">\r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n					<tbody>\r\n						<tr>\r\n							<td style=\"padding: 20px 0px;\">\r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>\r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">¡Notificación de mensajes no leídos!</h2></td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom-style: solid; border-bottom-color: rgb(238, 238, 238); background: rgb(255, 255, 255); padding: 0px 40px 50px; color: rgb(153, 153, 153); vertical-align: top;\">\r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\r\n					<tbody>\r\n						<tr>\r\n							<td style=\"padding: 40px 0px 60px;\">\r\n								<h3 style=\"margin: 0px 0px 10px; font-size: 24px; font-weight: 500; padding: 0px; color: rgb(51, 51, 51); text-align: center;\">Estimado {user_full_name}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px; color: rgb(103, 103, 103);\">Estas son algunas de las notificaciones que te has perdido de los siguientes hilos:</p>{messages_detail}</td>\r\n						</tr>\r\n					</tbody>\r\n				</table></td>\r\n		</tr>\r\n	</tbody>\r\n</table>', '{user_full_name} Name of the email receiver.<br>\r\n{unread_messages_count} Unread messages count.<br>\r\n{messages_detail} Threads list.<br>\r\n{website_name} Name of our website<br>', 1, 0),
('user_admin_password_changed_successfully', 1, 'User/Admin Password Changed Successfully', 'Password reset successfully {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Congratulations</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {user_full_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">This mail is to ensure that you have recently updated your password.<br />\r\n									 Your password update process is successful and now you can login with your new password.</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><a style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\" href=\"{login_link}\">Login</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />\r\n									If you have not updated your password, we recommend you to reset your password immediately.</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{user_full_name} User Full Name<br>\\r\\n{website_name} Website Name<br>\\r\\n{website_url} Website Url<br>\\r\\n{login_link} Login Page Link', 1, 0),
('user_admin_password_changed_successfully', 2, 'تم تغيير كلمة مرور المستخدم / المسؤول بنجاح', 'تمت إعادة تعيين كلمة المرور بنجاح {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">مبروك</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {user_full_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">هذا البريد هو للتأكد من أنك قمت مؤخرا بتحديث كلمة المرور الخاصة بك.<br />عملية تحديث كلمة المرور الخاصة بك ناجحة والآن يمكنك تسجيل الدخول باستخدام كلمة المرور الجديدة.</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><a style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\" href=\"{login_link}\">تسجيل الدخول</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />إذا لم تقم بتحديث كلمة المرور الخاصة بك ، نوصيك بإعادة تعيين كلمة المرور الخاصة بك على الفور.</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{user_full_name} User Full Name<br>\\r\\n{website_name} Website Name<br>\\r\\n{website_url} Website Url<br>\\r\\n{login_link} Login Page Link', 1, 0),
('user_admin_password_changed_successfully', 3, 'La contraseña de usuario/administrador se ha cambiado correctamente', 'Restablecimiento de contraseña con éxito {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Felicidades</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {user_full_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Este correo es para asegurarse de que ha actualizado recientemente su contraseña.<br />Su proceso de actualización de contraseña se ha realizado correctamente y ahora puede iniciar sesión con su nueva contraseña.</p>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><a style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\" href=\"{login_link}\">Iniciar sesión</a></p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"><br />Si no ha actualizado su contraseña, le recomendamos que la restablezca inmediatamente.</p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{user_full_name} User Full Name<br>\\r\\n{website_name} Website Name<br>\\r\\n{website_url} Website Url<br>\\r\\n{login_link} Login Page Link', 1, 0),
('user_email_change_verification', 1, 'Email Verification Link', 'Email Verification at {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Email Verification!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {user_full_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"> We have received an email update request from your account.</p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">You are almost done!!<br />\r\n									But before being able to access your account with new email, you just need to verify your email address by clicking on below button:</p>                                                                <a href=\"{verification_url}\" style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\">Verify Account</a>                                                                \r\n								<p style=\"font-size: 14px;line-height: 20px;color: #676767;\">Or copy &amp; paste this url to your web browser: <a style=\"color:{primary-color};\" href=\"javascript:void(0);\">{verification_url}</a></p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{user_full_name} Name of the email receiver.<br> \r\n{verification_url} Url to verify email<br> {website_name} - Website Name<br>', 1, 1);
INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('user_email_change_verification', 2, 'رابط التحقق من البريد الإلكتروني', 'التحقق من البريد الإلكتروني في {website_name}', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0;\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">التحقق من البريد الإلكتروني!</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">عزيزي {user_full_name}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\"> لقد تلقينا طلب تحديث عبر البريد الإلكتروني من حسابك.</p>                                                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">لقد أوشكت على الانتهاء!!<br />ولكن قبل أن تتمكن من الوصول إلى حسابك باستخدام بريد إلكتروني جديد ، ما عليك سوى التحقق من عنوان بريدك الإلكتروني بالنقر فوق الزر أدناه:</p>                                                                <a href=\"{verification_url}\" style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\">التحقق من الحساب</a>                                                                \r\n								<p style=\"font-size: 14px;line-height: 20px;color: #676767;\">أو انسخ عنوان url هذا والصقه في متصفح الويب الخاص بك: <a style=\"color:{primary-color};\" href=\"javascript:void(0);\">{verification_url}</a></p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', '{user_full_name} Name of the email receiver.<br> \r\n{verification_url} Url to verify email<br> {website_name} - Website Name<br>', 1, 1),
