(18, 'How To Start Learning?', 18, 1, 1, 1, '<section class=\"section section--HowItWorks\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<h2>How w3mentors Works</h2>        </div>        \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<nav class=\"inline-tabs\">                \r\n				<ul class=\"nav nav-pills justify-content-md-center gap-3\" id=\"howitworksTab\" role=\"tablist\">\r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link active\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__1\" aria-controls=\"tab__1\" aria-selected=\"true\" type=\"button\">Choose Your Tutor</button>                    </li>                    \r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__2\" aria-controls=\"tab__2\" aria-selected=\"false\" type=\"button\">Become an Expert</button>                    </li>                    \r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__3\" aria-controls=\"tab__3\" aria-selected=\"false\" type=\"button\">Book Your Lesson</button>                    </li>                \r\n				</ul>            </nav>            \r\n			<div class=\"flex-layout-wrapper\" id=\"howitworksTabContent\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n				<div class=\"fade tab-pane show active\" role=\"tabpanel\" id=\"tab__1\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"> <img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Choose Your Tutor</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Explore tutor\'s profile, qualifications, subjects taught, and experience. </li>                                    \r\n									<li>Find a tutor who fits your schedule with flexible time slots. </li>                                    \r\n									<li>See feedback from other students to make an informed choice. </li>                                    \r\n									<li>Reserve your spot with just a few clicks and start learning!</li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>                \r\n				<div class=\"fade tab-pane\" role=\"tabpanel\" id=\"tab__2\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"> <img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Become an Expert</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Set your own availability and teach at your convenience. </li>                                    \r\n									<li>Earn for every session you teach with secure payments. </li>                                    \r\n									<li>Manage bookings, track progress, and interact with students effortlessly. </li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>                \r\n				<div class=\"fade tab-pane\" role=\"tabpanel\" id=\"tab__3\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"> <img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Book Your FREE Lesson</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Browse experienced tutors and schedule lessons with the tutor tailored to your needs.</li>                                    \r\n									<li>Complete your payment to confirm your booking. </li>                                    \r\n									<li>Join your lessons online with user-friendly meeting tools.</li>                                    \r\n									<li>24/7 Teacher Support – Learn Anytime, Anywhere!</li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div></section>', 7),
(19, 'Affiliate Register banner section', 19, 6, 1, 1, '<h3><span style=\"font-size: 36pt;\">Make Money with Our Affiliate Program!</span></h3>\n<ul>\n	<li> <span style=\"font-size: 14pt;\">Joining our affiliate program is simple and free! You can earn revenue by referring potential customers to our website. </span></li>\n	<li><span style=\"font-size: 14pt;\">  Whether you\'re a big content network, active on social media, or an experienced blogger, you can earn commissions on referred purchases and sign-ups. </span></li>\n	<li><span style=\"font-size: 14pt;\">For more information, please visit our FAQ page, and don\'t forget to read our Terms &amp; Conditions!</span></li>\n</ul>', 4),
(20, 'Popular Subjects', 20, 1, 0, 1, '', 1),
(21, 'Browse Courses section', 21, 1, 1, 1, '<section class=\"section\">\r\n <div class=\"container container--xxl\">\r\n <div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n <div class=\"cta-content\">\r\n <h6>Premium learning experience</h6>\r\n <h2>Providing Amazing Online Courses.</h2>\r\n <a class=\"btn btn--primary btn--large\" href=\"courses\">View Courses</a>\r\n </div>\r\n </div>\r\n </div>\r\n</section>', 2),
(22, 'Creating A Community Section', 22, 1, 1, 1, '<section class=\"section\">\r\n	<div class=\"container container--xxl\">\r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h2>Creating a community of life long learners.</h2>\r\n		</div>\r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"stats-wrapper\">\r\n				<div class=\"stats-listing\">\r\n					<div class=\"stats\">\r\n						<span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span>\r\n						<span class=\"stats__label\">Learners & Teachers</span>\r\n					</div>\r\n					<div class=\"stats\">\r\n						<span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span>\r\n						<span class=\"stats__label\">Total Courses</span>\r\n					</div>\r\n					<div class=\"stats\">\r\n						<span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span>\r\n						<span class=\"stats__label\">Total Posts</span>\r\n					</div>\r\n					<div class=\"stats\">\r\n						<span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span>\r\n						<span class=\"stats__label\">Registered Users</span>\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</section>', 6),
(23, 'Courses with Categories', 23, 1, 0, 1, '', 4),
(24, 'Join Now Section', 24, 1, 1, 1, '<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Join now to start learning</h2>                        \r\n						<p>Learn from our quality tutors!</p>                        <a href=\"guest-user/register-form\" class=\"btn btn--primary btn--large\">Get Started</a>                    </div>                </div>            </div>            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img-2.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Become a new tutor</h2>                        \r\n						<p>Teach thousands of students and earn money!</p>                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">Get Started</a>                    </div>                </div>            </div>        </div>    </div></section>', 12),
(25, 'Subscription Plans', 25, 1, 0, 0, '', 14),
(26, 'Got Questions Section', 26, 3, 1, 1, '<div class=\"cms-cta\"> \n <div class=\"cms-cta__content\"> \n <h2> Got questions?\n <span style=\"display:block;\">Request a call-back</span> </h2> <a href=\"/contact\" class=\"btn btn--primary\">Contact us</a> </div> \n <div class=\"cms-cta__media\"> <img src=\"/image/editor-image/cta-img.png\" alt=\"Contact\" /> </div></div>', 0);
INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
(1, 1, 'Teacher Profile info bar', '\r\n<ul>\r\n	<li>Profile needs to be at least 80% completed.</li>\r\n	<li>Please select the preferred languages and lesson prices.</li>\r\n	<li>After verifying account settings, mark your availability calendar to start teaching.</li>\r\n</ul>'),
(1, 2, 'شريط معلومات ملف تعريف المعلم', '\r\n<ul>\r\n	<li>يجب أن يكون الملف الشخصي مكتمل بنسبة 80٪ على الأقل.</li>\r\n	<li>يرجى تحديد اللغات المفضلة وأسعار الدروس.</li>\r\n	<li>بعد التحقق من إعدادات الحساب ، ضع علامة على تقويم التوفر لبدء التدريس.</li>\r\n</ul>'),
(1, 3, 'Barra de información del perfil del profesor', '\r\n<ul>\r\n	<li>El perfil debe completarse al menos en un 80%.</li>\r\n	<li>Por favor, seleccione los idiomas preferidos y los precios de las lecciones.</li>\r\n	<li>Después de verificar la configuración de la cuenta, marque su calendario de disponibilidad para comenzar a enseñar.</li>\r\n</ul>'),
(2, 1, 'Why Us Block', '\r\n<div class=\"container container--xxl\">                \r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n		<h2>We Make Language Learning Easy &amp; Simpler</h2>                </div>                \r\n	<div class=\"section__body\">                    \r\n		<div class=\"grid-blocks\">                        \r\n			<div class=\"cms-block\" data-aos=\"fade-right\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__1.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Professional Tutors</h3>                                \r\n					<p>Choose from over a myriad of professional &amp; experienced teachers to be fluent in any language.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-up\" data-aos-duration=\"600\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__2.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>1-on-1 Live sessions</h3>                                \r\n					<p>Connect with your teachers via 1-on-1 live chat sessions and build a deeper understanding of a language.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-left\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__3.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Group Classes</h3>                                \r\n					<p>Feel motivated, enthusiastic, and improve your social interaction via group lessons.</p>                            </div>                        </div>                    </div>                </div>            </div>'),
(2, 2, 'لماذا نحن الحظر', '\r\n<div class=\"container container--xxl\">                \r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n		<h2>نجعل تعلم اللغة سهلا وأبسط</h2>                </div>                \r\n	<div class=\"section__body\">                    \r\n		<div class=\"grid-blocks\">                        \r\n			<div class=\"cms-block\" data-aos=\"fade-right\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__1.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>مدرسون محترفون</h3>                                \r\n					<p>اختر من بين عدد لا يحصى من المعلمين المحترفين وذوي الخبرة لتكون بطلاقة في أي لغة.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-up\" data-aos-duration=\"600\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__2.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>جلسات مباشرة 1 على 1</h3>                                \r\n					<p>تواصل مع معلميك عبر جلسات الدردشة المباشرة الفردية وقم ببناء فهم أعمق للغة.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-left\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__3.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>فصول جماعية</h3>                                \r\n					<p>اشعر بالدافع والحماس وحسن تفاعلك الاجتماعي من خلال دروس المجموعة.</p>                            </div>                        </div>                    </div>                </div>            </div>'),
(2, 3, '¿Por qué bloqueamos?', '\r\n<div class=\"container container--xxl\">                \r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n		<h2>Hacemos que el aprendizaje de idiomas sea fácil y sencillo</h2>                </div>                \r\n	<div class=\"section__body\">                    \r\n		<div class=\"grid-blocks\">                        \r\n			<div class=\"cms-block\" data-aos=\"fade-right\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__1.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Tutores Profesionales</h3>                                \r\n					<p>Elija entre una gran cantidad de profesores profesionales y experimentados para hablar con fluidez cualquier idioma.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-up\" data-aos-duration=\"600\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__2.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Sesiones en vivo 1 a 1</h3>                                \r\n					<p>Conéctate con tus profesores a través de sesiones de chat en vivo 1 a 1 y desarrolla una comprensión más profunda de un idioma.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-left\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__3.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Clases Grupales</h3>                                \r\n					<p>Siéntete motivado, entusiasta y mejora tu interacción social a través de lecciones grupales.</p>                            </div>                        </div>                    </div>                </div>            </div>'),
(3, 1, 'Browse Teacher', '\r\n<section class=\"section\"> \r\n	<div class=\"container container--xxl\"> \r\n		<div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\"> \r\n			<div class=\"cta-content\"> \r\n				<h6></h6> \r\n				<h2>Learn any Subject with the help of professional teachers</h2> <a class=\"btn btn--primary btn--large\" href=\"teachers\">Browse Teachers</a> </div> </div> </div></section> '),
(3, 2, 'تصفح المعلم', '\r\n<section class=\"section\"> \r\n	<div class=\"container container--xxl\"> \r\n		<div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\"> \r\n			<div class=\"cta-content\"> \r\n				<h6></h6> \r\n				<h2>تعلم أي مادة بمساعدة معلمين محترفين</h2><a class=\"btn btn--primary btn--large\" href=\"teachers\">تصفح المعلمين</a> </div> </div> </div></section> '),
(3, 3, 'Buscar Profesor', '\r\n<section class=\"section\"> \r\n	<div class=\"container container--xxl\"> \r\n		<div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\"> \r\n			<div class=\"cta-content\"> \r\n				<h6></h6> \r\n				<h2>Aprende cualquier tema con la ayuda de profesores profesionales</h2><a class=\"btn btn--primary btn--large\" href=\"teachers\">Buscar profesores</a> </div> </div> </div></section> '),
