(18, 1, 'How To Start Learning?', '\r\n<section class=\"section section--HowItWorks\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<h2>How w3mentors Works</h2>        </div>        \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<nav class=\"inline-tabs\">                \r\n				<ul class=\"nav nav-pills justify-content-md-center gap-3\" id=\"howitworksTab\" role=\"tablist\">\r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link active\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__1\" aria-controls=\"tab__1\" aria-selected=\"true\" type=\"button\">Choose Your Tutor</button>                    </li>                    \r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__2\" aria-controls=\"tab__2\" aria-selected=\"false\" type=\"button\">Become an Expert</button>                    </li>                    \r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__3\" aria-controls=\"tab__3\" aria-selected=\"false\" type=\"button\">Book Your Lesson</button>                    </li>                \r\n				</ul>            </nav>            \r\n			<div class=\"flex-layout-wrapper\" id=\"howitworksTabContent\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n				<div class=\"fade tab-pane show active\" role=\"tabpanel\" id=\"tab__1\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"> <img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Choose Your Tutor</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Explore tutor\'s profile, qualifications, subjects taught, and experience. </li>                                    \r\n									<li>Find a tutor who fits your schedule with flexible time slots. </li>                                    \r\n									<li>See feedback from other students to make an informed choice. </li>                                    \r\n									<li>Reserve your spot with just a few clicks and start learning!</li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>                \r\n				<div class=\"fade tab-pane\" role=\"tabpanel\" id=\"tab__2\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"> <img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Become an Expert</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Set your own availability and teach at your convenience. </li>                                    \r\n									<li>Earn for every session you teach with secure payments. </li>                                    \r\n									<li>Manage bookings, track progress, and interact with students effortlessly. </li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>                \r\n				<div class=\"fade tab-pane\" role=\"tabpanel\" id=\"tab__3\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"> <img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Book Your FREE Lesson</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Browse experienced tutors and schedule lessons with the tutor tailored to your needs.</li>                                    \r\n									<li>Complete your payment to confirm your booking. </li>                                    \r\n									<li>Join your lessons online with user-friendly meeting tools.</li>                                    \r\n									<li>24/7 Teacher Support – Learn Anytime, Anywhere!</li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div></section>'),
(18, 2, 'كيف تبدأ التعلم؟', '\r\n<section class=\"section section--HowItWorks\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<h2>كيف يو! أعمال المدرب</h2>        </div>        \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<nav class=\"inline-tabs\">                \r\n				<ul class=\"nav nav-pills justify-content-md-center gap-3\" id=\"howitworksTab\" role=\"tablist\">\r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link active\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__1\" aria-controls=\"tab__1\" aria-selected=\"true\" type=\"button\">اختر مدرسك</button>                    </li>                    \r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__2\" aria-controls=\"tab__2\" aria-selected=\"false\" type=\"button\">كن خبيرا</button>                    </li>                    \r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__3\" aria-controls=\"tab__3\" aria-selected=\"false\" type=\"button\">احجز درسك</button>                    </li>                \r\n				</ul>            </nav>            \r\n			<div class=\"flex-layout-wrapper\" id=\"howitworksTabContent\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n				<div class=\"fade tab-pane show active\" role=\"tabpanel\" id=\"tab__1\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>اختر مدرسك</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>استكشف ملف تعريف المعلم ومؤهلاته والمواد التي يتم تدريسها وخبرته. </li>                                    \r\n									<li>ابحث عن مدرس يناسب جدولك الزمني بفترات زمنية مرنة. </li>                                    \r\n									<li>اطلع على التعليقات الواردة من الطلاب الآخرين لاتخاذ قرار مستنير. </li>                                    \r\n									<li>احجز مكانك ببضع نقرات فقط وابدأ التعلم!</li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>                \r\n				<div class=\"fade tab-pane\" role=\"tabpanel\" id=\"tab__2\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>كن خبيرا</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>حدد توافرك الخاص وقم بالتدريس على راحتك. </li>                                    \r\n									<li>اربح مقابل كل جلسة تقوم بتدريسها من خلال مدفوعات آمنة. </li>                                    \r\n									<li>إدارة الحجوزات وتتبع التقدم والتفاعل مع الطلاب دون عناء. </li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>                \r\n				<div class=\"fade tab-pane\" role=\"tabpanel\" id=\"tab__3\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>احجز درسك المجاني</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>تصفح المعلمين ذوي الخبرة وجدولة الدروس مع المعلم المصمم خصيصا لاحتياجاتك.</li>                                    \r\n									<li>أكمل الدفع لتأكيد حجزك. </li>                                    \r\n									<li>انضم إلى دروسك عبر الإنترنت باستخدام أدوات اجتماعات سهلة الاستخدام.</li>                                    \r\n									<li>دعم المعلم 24/7 - تعلم في أي وقت وفي أي مكان!</li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div></section>'),
(18, 3, '¿Cómo empezar a aprender?', '\r\n<section class=\"section section--HowItWorks\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<h2>¡Cómo Yo! Trabajos de autocar</h2>        </div>        \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<nav class=\"inline-tabs\">                \r\n				<ul class=\"nav nav-pills justify-content-md-center gap-3\" id=\"howitworksTab\" role=\"tablist\">\r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link active\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__1\" aria-controls=\"tab__1\" aria-selected=\"true\" type=\"button\">Elige a tu tutor</button>                    </li>                    \r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__2\" aria-controls=\"tab__2\" aria-selected=\"false\" type=\"button\">Conviértete en un experto</button>                    </li>                    \r\n					<li class=\"nav-item\" role=\"presentation\">                        \r\n						<button class=\"inline-tabs-link\" data-bs-toggle=\"tab\" role=\"tab\" data-bs-target=\"#tab__3\" aria-controls=\"tab__3\" aria-selected=\"false\" type=\"button\">Reserva tu clase</button>                    </li>                \r\n				</ul>            </nav>            \r\n			<div class=\"flex-layout-wrapper\" id=\"howitworksTabContent\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n				<div class=\"fade tab-pane show active\" role=\"tabpanel\" id=\"tab__1\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Elige a tu tutor</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Explore el perfil del tutor, las calificaciones, las materias impartidas y la experiencia. </li>                                    \r\n									<li>Encuentre un tutor que se adapte a su horario con franjas horarias flexibles. </li>                                    \r\n									<li>Vea los comentarios de otros estudiantes para tomar una decisión informada. </li>                                    \r\n									<li>¡Reserva tu lugar con solo unos clics y comienza a aprender!</li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>                \r\n				<div class=\"fade tab-pane\" role=\"tabpanel\" id=\"tab__2\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Conviértete en un experto</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Establezca su propia disponibilidad y enseñe a su conveniencia. </li>                                    \r\n									<li>Gana por cada sesión que impartas con pagos seguros. </li>                                    \r\n									<li>Administre reservas, realice un seguimiento del progreso e interactúe con los estudiantes sin esfuerzo. </li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>                \r\n				<div class=\"fade tab-pane\" role=\"tabpanel\" id=\"tab__3\">                    \r\n					<div class=\"flex-layout\">                        \r\n						<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /> </div>                        \r\n						<div class=\"flex-layout__content\">                            \r\n							<div class=\"content\">                                \r\n								<h2>Reserva tu clase GRATIS</h2>                                \r\n								<ul class=\"list list--circle\">                                    \r\n									<li>Busque tutores experimentados y programe lecciones con el tutor según sus necesidades.</li>                                    \r\n									<li>Complete su pago para confirmar su reserva. </li>                                    \r\n									<li>Únase a sus lecciones en línea con herramientas de reunión fáciles de usar.</li>                                    \r\n									<li>Apoyo al maestro las 24 horas del día, los 7 días de la semana: ¡aprenda en cualquier momento y en cualquier lugar!</li>                                \r\n								</ul>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div></section>'),
(19, 1, 'Become an Affiliate Today!', '<h3><span style=\"font-size: 36pt;\">Make Money with Our Affiliate Program!</span></h3>\r\n<ul>\r\n	<li> <span style=\"font-size: 14pt;\">Joining our affiliate program is simple and free! You can earn revenue by referring potential customers to our website. </span></li>\r\n	<li><span style=\"font-size: 14pt;\">  Whether you\'re a big content network, active on social media, or an experienced blogger, you can earn commissions on referred purchases and sign-ups. </span></li>\r\n	<li><span style=\"font-size: 14pt;\">For more information, please visit our FAQ page, and don\'t forget to read our Terms &amp; Conditions!</span></li>\r\n</ul>'),
(19, 2, 'كن تابعا اليوم!', '<h3><span style=\"font-size: 36pt;\">كسب المال مع برنامج الانتساب لدينا!</span></h3>\r\n<ul>\r\n	<li> <span style=\"font-size: 14pt;\"> الانضمام إلى برنامج الانتساب الخاص بنا بسيط ومجاني! يمكنك كسب الإيرادات عن طريق إحالة العملاء المحتملين إلى موقعنا. </span></li>\r\n	<li><span style=\"font-size: 14pt;\">  سواء كنت شبكة محتوى كبيرة أو نشطة على وسائل التواصل الاجتماعي أو مدونا متمرسا ، يمكنك كسب عمولات على عمليات الشراء والاشتراكات المشار إليها. </span></li>\r\n	<li><span style=\"font-size: 14pt;\">لمزيد من المعلومات، يرجى زيارة صفحة الأسئلة الشائعة، ولا تنس قراءة الشروط والأحكام الخاصة بنا!</span></li>\r\n</ul>'),
(19, 3, '¡Conviértase en afiliado hoy!', '\r\n<h3><span style=\"font-size: 36pt;\">¡Gane dinero con nuestro programa de afiliados!</span></h3>\r\n<ul>\r\n	<li> <span style=\"font-size: 14pt;\">¡Unirse a nuestro programa de afiliados es simple y gratis! Puede obtener ingresos refiriendo clientes potenciales a nuestro sitio web. </span></li>\r\n<li> <span style=\"font-size: 14pt;\"> Ya sea que sea una gran red de contenido, activo en las redes sociales o un bloguero experimentado, puede ganar comisiones por las compras y registros referidos. </span></li>\r\n<li> <span style=\"font-size: 14pt;\">Para obtener más información, visite nuestra página de preguntas frecuentes y no olvide leer nuestros T&eacute;rminos y condiciones. </span></li>\r\n</ul>'),
(20, 1, 'Popular Subjects', ''),
(20, 2, 'المواضيع الشعبية', ''),
(20, 3, 'Temas populares', ''),
(21, 1, 'Browse Courses', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"cta-content\">                \r\n				<h6>Premium learning experience</h6>                \r\n				<h2>Providing Amazing Online Courses.</h2>                <a class=\"btn btn--primary btn--large\" href=\"courses\">View Courses</a>            </div>        </div>    </div></section> '),
(21, 2, 'تصفح الدورات', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"cta-content\">                \r\n				<h6>تجربة تعليمية متميزة</h6>                \r\n				<h2>تقديم دورات مذهلة عبر الإنترنت.</h2>                <a class=\"btn btn--primary btn--large\" href=\"courses\">عرض الدورات</a>            </div>        </div>    </div></section> '),
(21, 3, 'Buscar cursos', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"cta-content\">                \r\n				<h6>Experiencia de aprendizaje premium</h6>                \r\n				<h2>Brindando increíbles cursos en línea.</h2>                <a class=\"btn btn--primary btn--large\" href=\"courses\">Ver Cursos</a>            </div>        </div>    </div></section>  '),
(22, 1, 'Creating A Community Section', '\r\n<section class=\"section\">\r\n	<div class=\"container container--xxl\">\r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h2>Creating a community of life long learners.</h2></div>\r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"stats-wrapper\">\r\n				<div class=\"stats-listing\">\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span><span class=\"stats__label\">Learners &amp; Teachers</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span><span class=\"stats__label\">Total Courses</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span><span class=\"stats__label\">Total Posts</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span><span class=\"stats__label\">Registered Users</span></div></div></div></div></div></section>'),
(22, 2, 'إنشاء قسم المجتمع', '\r\n<section class=\"section\">\r\n	<div class=\"container container--xxl\">\r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h2>خلق مجتمع من المتعلمين مدى الحياة.</h2></div>\r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"stats-wrapper\">\r\n				<div class=\"stats-listing\">\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span><span class=\"stats__label\">متعلمون ومعلمون</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span><span class=\"stats__label\">إجمالي الدورات</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span><span class=\"stats__label\">إجمالي المشاركات</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span><span class=\"stats__label\">مستخدم مسجل</span></div></div></div></div></div></section>'),
(22, 3, 'Creación de una sección de la comunidad', '\r\n<section class=\"section\">\r\n	<div class=\"container container--xxl\">\r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h2>Crear una comunidad de aprendices a lo largo de toda la vida.</h2></div>\r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"stats-wrapper\">\r\n				<div class=\"stats-listing\">\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span> <span class=\"stats__label\">Aprendices y Profesores</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span><span class=\"stats__label\">Cursos en total</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span> <span class=\"stats__label\">Publicaciones Totales</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span> <span class=\"stats__label\">Usuarios Registrados</span></div></div></div></div></div></section>'),
