(24, 1, 'Join Now', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Join now to start learning</h2>                        \r\n						<p>Learn from our quality tutors!</p>                        <a href=\"guest-user/register-form\" class=\"btn btn--primary btn--large\">Get Started</a>                    </div>                </div>            </div>            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img-2.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Become a new tutor</h2>                        \r\n						<p>Teach thousands of students and earn money!</p>                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">Get Started</a>                    </div>                </div>            </div>        </div>    </div></section>'),
(24, 2, 'اشترك الآن', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>انضم الآن لبدء التعلم</h2>                        \r\n						<p>تعلم من مدرسينا ذوي الجودة العالية!</p>                        <a href=\"guest-user/register-form\" class=\"btn btn--primary btn--large\">ابدأ الآن</a>                    </div>                </div>            </div>            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img-2.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>كن مدرسا جديدا</h2>                        \r\n						<p>علم آلاف الطلاب واكسب المال!</p>                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">ابدأ الآن</a>                    </div>                </div>            </div>        </div>    </div></section>'),
(24, 3, 'Únete ahora', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Únete ahora para empezar a aprender</h2>                        \r\n						<p>¡Aprende de nuestros tutores de calidad!</p>                        <a href=\"guest-user/register-form\" class=\"btn btn--primary btn--large\">Comenzar</a>                    </div>                </div>            </div>            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img-2.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Conviértete en un nuevo tutor</h2>                        \r\n						<p>¡Enseña a miles de estudiantes y gana dinero!</p>                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">Comenzar</a>                    </div>                </div>            </div>        </div>    </div></section>'),
