(26, 1, 'Got Questions Section', '\r\n<div class=\"cms-cta\"> \r\n	<div class=\"cms-cta__content\"> \r\n		<h2> Got questions?\r\n <span style=\"display:block;\">Request a call-back</span> </h2> <a href=\"/contact\" class=\"btn btn--primary\">Contact us</a> </div> \r\n \r\n	<div class=\"cms-cta__media\"> <img src=\"/image/editor-image/cta-img.png\" alt=\"Contact\" /> </div></div> '),
(26, 2, 'قسم الأسئلة', '<div class=\"cms-cta\">\n <div class=\"cms-cta__content\">\n <h2>هل لديك أسئلة؟<span style=\"display:block;\">طلب معاودة الاتصال</span></h2><a href=\"/contact\" class=\"btn btn--primary\">اتصل بنا</a></div>\n <div class=\"cms-cta__media\"><img src=\"/image/editor-image/cta-img.png\" alt=\"Contact\" /></div></div>'),
